<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pledgeId=filter_input(INPUT_GET,'pledge',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'pledge_id',FILTER_VALIDATE_INT);if(!$pledgeId)redirect('donor/dashboard.php');$pdo=db();
$stmt=$pdo->prepare("SELECT dp.*,cr.title,cr.collection_location,cr.collection_notes,c.organization_name,c.id charity_id FROM donation_pledges dp JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id WHERE dp.id=? AND dp.donor_id=?");$stmt->execute([$pledgeId,$user['id']]);$pledge=$stmt->fetch();if(!$pledge||!in_array($pledge['status'],['approved','scheduled'],true)){flash('error','This pledge is not ready for appointment booking.');redirect('donor/dashboard.php');}$error='';
$slots=['09:00:00','10:00:00','11:00:00','13:00:00','14:00:00','15:00:00','16:00:00'];
if(is_post()){verify_csrf();$date=$_POST['appointment_date']??'';$slot=$_POST['time_slot']??'';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d'))$error='Choose a future drop-off date.';elseif(!in_array($slot,$slots,true))$error='Choose one of the available time slots.';else{$capacity=$pdo->prepare("SELECT COUNT(*) FROM appointments a JOIN donation_pledges dp ON dp.id=a.pledge_id JOIN clothing_requests cr ON cr.id=dp.request_id WHERE cr.charity_id=? AND a.appointment_date=? AND a.time_slot=? AND a.status='booked'");$capacity->execute([$pledge['charity_id'],$date,$slot]);if((int)$capacity->fetchColumn()>=5)$error='That slot has just filled up. Please choose another time.';else{$pdo->beginTransaction();try{$pdo->prepare("DELETE FROM appointments WHERE pledge_id=? AND status='booked'")->execute([$pledgeId]);$pdo->prepare("INSERT INTO appointments (pledge_id,appointment_date,time_slot,status) VALUES (?,?,?,'booked')")->execute([$pledgeId,$date,$slot]);$appointmentId=(int)$pdo->lastInsertId();appointment_qr_token($pdo,$appointmentId);$pdo->prepare("UPDATE donation_pledges SET status='scheduled',updated_at=NOW() WHERE id=?")->execute([$pledgeId]);create_notification($pdo,(int)$user['id'],'appointment','Drop-off booked','Your QR check-in pass is ready for '.$date.' at '.substr($slot,0,5).'.','donor/appointments.php');log_activity($pdo,'booked a drop-off appointment',(int)$user['id'],'pledge',$pledgeId);$pdo->commit();flash('success','Your drop-off is booked. Your QR check-in pass is ready.');redirect('donor/appointments.php');}catch(Throwable $e){$pdo->rollBack();$error='We could not book that appointment. Please try again.';}}}}
$pageTitle='Book your drop-off';require __DIR__ . '/../includes/header.php'; ?>
<section class="auth-page"><div class="auth-card" style="width:min(650px,100%)"><span class="eyebrow">Almost there</span><h1>Pick a drop-off time.</h1><p><strong><?=e($pledge['title'])?></strong><br>📍 <?=e($pledge['collection_location'])?><br><?=e($pledge['collection_notes']?:'Bring clean, wearable items.')?></p><?php if($error):?><div class="flash flash-error"><span><?=e($error)?></span></div><?php endif;?><form method="post" data-loading><?=csrf_field()?><input type="hidden" name="pledge_id" value="<?=$pledgeId?>"><div class="form-grid"><div class="field"><label for="appointment_date">Date</label><input class="input" type="date" min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+60 days'))?>" id="appointment_date" name="appointment_date" required value="<?=e($_POST['appointment_date']??'')?>"></div><div class="field"><label for="time_slot">Time slot</label><select class="select" name="time_slot" id="time_slot" required><option value="">Select a time</option><?php foreach($slots as $slot):?><option value="<?=$slot?>" <?=($_POST['time_slot']??'')===$slot?'selected':''?>><?=substr($slot,0,5)?></option><?php endforeach;?></select></div></div><p class="help">Each charity time slot holds up to five donor drop-offs.</p><div class="form-actions"><a class="button button-outline" href="<?=e(url('donor/dashboard.php'))?>">Back</a><button class="button" type="submit">Book drop-off →</button></div></form></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
